#!/usr/bin/env python3
"""orders pipeline — generated by etl-generator from orders.etlspec.yaml.

Transforms a vendor CSV export into the warehouse orders format.
Regenerate from the spec rather than editing transform logic by hand;
hand-edits and the spec will otherwise drift apart.
Error codes reference the ETL Failure-Mode Taxonomy v0.2.
"""
import argparse
import etl_runtime as rt

# ---- Resolved configuration (from orders.etlspec.yaml — edit the spec, not this) ----
CONFIG = {
    "name": "orders",
    "spec_version": "0.1",                       # etlspec format version (manifest, ERR-06)
    "generator_version": "etl-generator/0.2",    # what generated this pipeline (ERR-06)
    "encoding": "utf-8",
    "delimiter": ",",
    "quotechar": '"',
    # Header names post-trim (STR-04); " customer " -> "customer".
    "expected_columns": ["order_id", "customer", "amt", "order_date", "active", "zip", "notes"],
    "output_columns": ["order_id", "customer_name", "amount", "order_date",
                       "is_active", "postal_code", "notes"],
    "policies": {
        "unicode_normalization": "NFC",          # ENC-03
        "strip_control_chars": True,             # ENC-04
        "normalize_unicode_whitespace": True,    # ENC-05
        "repair_mojibake": True,                 # ENC-06 (opt-in; see spec review_required)
        "trim_whitespace": True,                 # NUL-02
        "empty_string_is_null": True,            # NUL-01
        "null_propagation": "sql",               # NUL-05
        "datetime_rendering": "iso8601",         # TYP-05
        "error_disposition": "quarantine",       # ERR-01
        "error_budget": {"percent": 5, "min_rows": 100},  # ERR-02
        "duplicate_rows": "keep",                # STR-05: exact dups kept + reported
        "sentinels": {"notes": ["N/A"]},         # NUL-03: applied during null resolution
    },
}

# STR-06: confirmed footer/aggregate rows are excluded via SkipRow, never treated
# as data. Matched case-insensitively against the cleaned order_id.
FOOTER_KEYWORDS = {"total", "totals", "subtotal", "grand total", "sum"}


def transform_row(row, rt_ctx):
    """Map one cleaned input row -> output row. Raise rt.RowError to reject a row,
    rt.SkipRow to exclude a non-data row.

    `row` values arrive already text-cleaned and null-resolved per policy
    (ENC-03/04/05, NUL-01/02/03 applied and counted by the runtime).
    """
    # STR-06: drop the 'Total,,3222.56,,,,' footer row (order_id is an aggregate keyword).
    oid = row["order_id"]
    if oid is not None and oid.casefold() in FOOTER_KEYWORDS:
        raise rt.SkipRow("STR-06", f"footer/aggregate row (order_id={oid!r})")

    out = {}
    # order_id <- order_id  [TYP-07: kept as string, 8-digit identifiers]
    out["order_id"] = rt.not_null(oid, "order_id")
    # customer_name <- customer  [ENC-06: repair mojibake (opt-in); ENC-03 NFC applied upstream]
    out["customer_name"] = rt.not_null(
        rt.repair_mojibake(row["customer"], "customer", rt_ctx), "customer")
    # amount <- amt  [TYP-01: strip $/thousands-commas, (n)=negative, scale 2 — detected-confirmed]
    out["amount"] = rt.to_decimal(row["amt"], "amt", thousands_sep=",",
                                  currency=True, accounting_negative=True, scale=2)
    # order_date <- order_date  [TYP-03: MDY — confirmed against target sample]
    out["order_date"] = rt.to_date(row["order_date"], "order_date", formats=["%m/%d/%Y"])
    # is_active <- active  [TYP-06: Y=true, N=false — detected-confirmed]
    out["is_active"] = rt.to_bool(row["active"], "active",
                                  mapping={"Y": True, "N": False}, report=rt_ctx)
    # postal_code <- zip  [TYP-07: string, leading zeros preserved (02134)]
    out["postal_code"] = rt.check_length(row["zip"], "zip", max_length=10)
    # notes <- notes  [NUL-03: 'N/A' -> null applied during null resolution]
    out["notes"] = row["notes"]
    return out


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("input")
    p.add_argument("--out-dir", default="./etl_out")
    args = p.parse_args()
    result = rt.run_pipeline(
        input_path=args.input,
        out_dir=args.out_dir,
        config=CONFIG,
        transform_row=transform_row,
    )
    raise SystemExit(result.exit_code)


if __name__ == "__main__":
    main()
